                        raise RuntimeError(f'upload not verified: {path}')
                    if not test:
                        CoverDB().update_completed_batch(self.item_id, self.batch_id, size=size)
                        os.remove(path)

    def finalize(self, start_id=None, test=True):
        self.process_pending(finalize=True, test=test)


@contextmanager
def batch_lock(item_id, batch_id):
    \"\"\"Serialize writers and finalizers for a batch on this coverserver.\"\"\"
    path = Batch.get_abspath(item_id, batch_id, ext='lock')
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'a+b') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}

    def add_file(self, name, filepath, mtime):
        match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.([A-Za-z0-9]+)', name)
        if not match:
            raise ValueError(f'invalid cover filename: {name}')
        item_id, batch_id = Cover.id_to_item_and_batch_id(match[1])
        size = (match[2] or '').lower()
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = (zf, set(zf.namelist()))
        zf, names = self.zipfiles[path]
        if name not in names:
            info = zipfile.ZipInfo(name, time.localtime(mtime)[:6])
            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            names.add(name)
        return os.path.basename(path)

    def close(self):
        for zf, _names in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()


def get_zipfile(name):
    match = re.fullmatch(r'(\\d{10})(?:-([SML]))?\\.[A-Za-z0-9]+', name)
    if not match:
        raise ValueError(f'invalid cover filename: {name}')
    item_id, batch_id = Cover.id_to_item_and_batch_id(match[1])
    return open_zipfile(Batch.get_abspath(item_id, batch_id, (match[2] or '').lower()))


def open_zipfile(path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def count_files_in_zip(filepath):
    with zipfile.ZipFile(filepath) as zf:
        return sum(name.lower().endswith('.jpg') for name in zf.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'], text=True, capture_output=True, check=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], text=True, capture_output=True, check=True)
        return zip_filename in result.stdout.splitlines()


class CoverDB:
    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (int(start_id) // 10_000 + 1) * 10_000 - 1

    def update_completed_batch(self, item_id, batch_id, ext='jpg', size=None):
        start = int(item_id) * 1_000_000 + int(batch_id) * 10_000
        end = self._get_batch_end_id(start)
        sizes = SIZES if size is None else (_size(size),)
        with self.db.transaction():
            covers = self.db.select('cover', where='id >= "'$start AND id <= $end AND archived = $yes AND failed = $no'"', vars={'start': start, 'end': end, 'yes': True, 'no': False})
            for cover in covers:
                fields = {('filename_' + s if s else 'filename'): Cover.get_cover_url(cover.id, s, ext) for s in sizes}
                fields['uploaded'] = True if size is None else all(
                    s in sizes or str(getattr(cover, 'filename_' + s if s else 'filename', '')).startswith(('http://', 'https://'))
                    for s in SIZES
                )
                self.db.update('cover', where='id="'$id'"', vars={'id': cover.id}, **fields)


